package com.jbrempresa.backend.entity;
import java.time.LocalDateTime; import com.fasterxml.jackson.annotation.JsonFormat; import jakarta.persistence.*;
@Entity @Table(name="codigos_postales") public class CodigoPostal {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="cop_id") private Long copId; @Column(name="emp_id",nullable=false) private Long empId; @Column(name="mun_id",nullable=false) private Long munId; @Column(name="cop_cod",nullable=false,length=10) private String copCod; @Column(name="cop_usu_mov",nullable=false,length=50) private String copUsuMov; @JsonFormat(pattern="dd/MM/yyyy HH:mm:ss") @Column(name="cop_fec_mov",nullable=false) private LocalDateTime copFecMov; @Column(name="cop_act",nullable=false) private Boolean copAct;
 public Long getCopId(){return copId;} public void setCopId(Long v){copId=v;} public Long getEmpId(){return empId;} public void setEmpId(Long v){empId=v;} public Long getMunId(){return munId;} public void setMunId(Long v){munId=v;} public String getCopCod(){return copCod;} public void setCopCod(String v){copCod=v;} public String getCopUsuMov(){return copUsuMov;} public void setCopUsuMov(String v){copUsuMov=v;} public LocalDateTime getCopFecMov(){return copFecMov;} public void setCopFecMov(LocalDateTime v){copFecMov=v;} public Boolean getCopAct(){return copAct;} public void setCopAct(Boolean v){copAct=v;}
}
